import{_ as a,c as t,o as r,ag as o}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"MFA Guide","description":"","frontmatter":{"title":"MFA Guide"},"headers":[],"relativePath":"general/mfa-guide.md","filePath":"general/mfa-guide.md","lastUpdated":null}'),i={name:"general/mfa-guide.md"};function n(s,e,h,c,d,l){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="mfa-guide" tabindex="-1">MFA Guide <a class="header-anchor" href="#mfa-guide" aria-label="Permalink to &quot;MFA Guide&quot;">​</a></h1><h2 id="what-is-mfa" tabindex="-1">What is MFA <a class="header-anchor" href="#what-is-mfa" aria-label="Permalink to &quot;What is MFA&quot;">​</a></h2><p><strong>Multi-factor authentication (MFA)</strong> is a layered approach to securing online accounts and their data. MFA requires users to provide two or more authenticators to verify their identity before accessing services. This method significantly reduces the likelihood of unauthorized access. According to Microsoft, users who enable MFA are significantly less likely to get hacked. Even if one factor, like a password, is compromised, unauthorized users cannot bypass the second authentication requirement.</p><p>MFA is also called Two-Factor Authentication (2FA), Multi-Factor Authentication, Two-Step Authentication, or UFA. All these terms refer to using a combination of what the user knows, has, or is to confirm identity online. <a href="https://www.cisa.gov/mfa" target="_blank" rel="noreferrer">Source: CISA</a></p><h3 id="mfa-combines-two-or-more-independent-credentials" tabindex="-1">MFA Combines Two or More Independent Credentials <a class="header-anchor" href="#mfa-combines-two-or-more-independent-credentials" aria-label="Permalink to &quot;MFA Combines Two or More Independent Credentials&quot;">​</a></h3><h2 id="what-the-user-knows-password" tabindex="-1">What the <strong>user knows</strong> (password). <a class="header-anchor" href="#what-the-user-knows-password" aria-label="Permalink to &quot;What the **user knows** (password).&quot;">​</a></h2><h2 id="what-the-user-has-security-token" tabindex="-1">What the <strong>user has</strong> (security token). <a class="header-anchor" href="#what-the-user-has-security-token" aria-label="Permalink to &quot;What the **user has** (security token).&quot;">​</a></h2><h2 id="what-the-user-is-biometric-verification" tabindex="-1">What the <strong>user is</strong> (biometric verification). <a class="header-anchor" href="#what-the-user-is-biometric-verification" aria-label="Permalink to &quot;What the **user is** (biometric verification).&quot;">​</a></h2><h3 id="mfa-backup-codes" tabindex="-1">MFA Backup Codes <a class="header-anchor" href="#mfa-backup-codes" aria-label="Permalink to &quot;MFA Backup Codes&quot;">​</a></h3><p>Backup One-Time Passcodes (OTP) are vital for deployments and should be part of every user&#39;s emergency plan. Situations prohibiting personal devices may require using backup OTP to access accounts. Securely store backup codes and ensure they are accessible during critical times.</p><h3 id="types-of-mfa" tabindex="-1">Types of MFA <a class="header-anchor" href="#types-of-mfa" aria-label="Permalink to &quot;Types of MFA&quot;">​</a></h3><ul><li><p><strong>(WEAKEST)</strong> Text Message (SMS) or Email: A service sends a code to your phone or email, which you use to log in. While better than no MFA, SMS/email-based authentication is considered the weakest form.</p></li><li><p>Authenticator App: Generates MFA codes on your smartphone. These codes typically expire every 30 or 60 seconds.</p></li><li><p>Push Notification: Instead of entering a code, you approve or deny a login request via a notification sent to your device.</p></li><li><p>FIDO Authentication: Utilizes secure biometric mechanisms or physical keys, providing a highly secure authentication method.</p></li><li><p><strong>(STRONGEST)</strong> Universal 2nd Factor (U2F): Hardware tokens such as CAC, Nitrokey, or Yubikey. These hardware tokens are phishing-resistant and use protocols like FIDO2 for enhanced security. <a href="https://www.yubico.com/authentication-standards/fido-u2f/" target="_blank" rel="noreferrer">Source: Yubico</a></p></li></ul><h3 id="how-to-enable-mfa" tabindex="-1">How To Enable MFA <a class="header-anchor" href="#how-to-enable-mfa" aria-label="Permalink to &quot;How To Enable MFA&quot;">​</a></h3><h3 id="app-mfa-totp" tabindex="-1">App MFA (TOTP) <a class="header-anchor" href="#app-mfa-totp" aria-label="Permalink to &quot;App MFA (TOTP)&quot;">​</a></h3><p>Follow these steps to enable MFA with an authenticator app:</p><h2 id="log-in-to-the-account" tabindex="-1">Log in to the account. <a class="header-anchor" href="#log-in-to-the-account" aria-label="Permalink to &quot;Log in to the account.&quot;">​</a></h2><h2 id="navigate-to-settings" tabindex="-1">Navigate to Settings. <a class="header-anchor" href="#navigate-to-settings" aria-label="Permalink to &quot;Navigate to Settings.&quot;">​</a></h2><h2 id="go-to-security-privacy" tabindex="-1">Go to Security &amp; Privacy. <a class="header-anchor" href="#go-to-security-privacy" aria-label="Permalink to &quot;Go to Security &amp; Privacy.&quot;">​</a></h2><h2 id="enable-or-set-up-multi-factor-authentication-mfa" tabindex="-1">Enable or set up Multi-Factor Authentication (MFA). <a class="header-anchor" href="#enable-or-set-up-multi-factor-authentication-mfa" aria-label="Permalink to &quot;Enable or set up Multi-Factor Authentication (MFA).&quot;">​</a></h2><h2 id="select-mobile-app-avoid-sms-unless-necessary" tabindex="-1">Select &quot;Mobile App&quot; (avoid SMS unless necessary). <a class="header-anchor" href="#select-mobile-app-avoid-sms-unless-necessary" aria-label="Permalink to &quot;Select &quot;Mobile App&quot; (avoid SMS unless necessary).&quot;">​</a></h2><h2 id="scan-the-qr-code-or-enter-the-mfa-seed-manually" tabindex="-1">Scan the QR Code or enter the MFA &quot;seed&quot; manually. <a class="header-anchor" href="#scan-the-qr-code-or-enter-the-mfa-seed-manually" aria-label="Permalink to &quot;Scan the QR Code or enter the MFA &quot;seed&quot; manually.&quot;">​</a></h2><h2 id="securely-store-the-mfa-seed-in-a-password-manager-or-encrypted-database" tabindex="-1">Securely store the MFA seed in a password manager or encrypted database. <a class="header-anchor" href="#securely-store-the-mfa-seed-in-a-password-manager-or-encrypted-database" aria-label="Permalink to &quot;Securely store the MFA seed in a password manager or encrypted database.&quot;">​</a></h2><h2 id="print-and-save-backup-keys-provided-by-the-service" tabindex="-1">Print and save backup keys provided by the service. <a class="header-anchor" href="#print-and-save-backup-keys-provided-by-the-service" aria-label="Permalink to &quot;Print and save backup keys provided by the service.&quot;">​</a></h2><h4 id="recommended-software-for-mfa" tabindex="-1">Recommended Software for MFA <a class="header-anchor" href="#recommended-software-for-mfa" aria-label="Permalink to &quot;Recommended Software for MFA&quot;">​</a></h4><ul><li><p><a href="https://apps.apple.com/us/app/otp-auth/id659877384" target="_blank" rel="noreferrer">OTP Auth (iOS)</a></p></li><li><p><a href="https://getaegis.app/" target="_blank" rel="noreferrer">Aegis (Android)</a></p></li><li><p><a href="https://addons.mozilla.org/en-US/firefox/addon/auth-helper/" target="_blank" rel="noreferrer">Authenticator (Firefox)</a></p></li></ul><h3 id="hardware-token-ufa" tabindex="-1">Hardware Token (UFA) <a class="header-anchor" href="#hardware-token-ufa" aria-label="Permalink to &quot;Hardware Token (UFA)&quot;">​</a></h3><p>Steps for enabling MFA using a hardware token:</p><h2 id="log-in-to-the-account-1" tabindex="-1">Log in to the account. <a class="header-anchor" href="#log-in-to-the-account-1" aria-label="Permalink to &quot;Log in to the account.&quot;">​</a></h2><h2 id="navigate-to-settings-1" tabindex="-1">Navigate to Settings. <a class="header-anchor" href="#navigate-to-settings-1" aria-label="Permalink to &quot;Navigate to Settings.&quot;">​</a></h2><h2 id="go-to-security-privacy-1" tabindex="-1">Go to Security &amp; Privacy. <a class="header-anchor" href="#go-to-security-privacy-1" aria-label="Permalink to &quot;Go to Security &amp; Privacy.&quot;">​</a></h2><h2 id="enable-or-add-hardware-keys" tabindex="-1">Enable or add &quot;Hardware keys.&quot; <a class="header-anchor" href="#enable-or-add-hardware-keys" aria-label="Permalink to &quot;Enable or add &quot;Hardware keys.&quot;&quot;">​</a></h2><h2 id="insert-the-hardware-token-when-prompted" tabindex="-1">Insert the hardware token when prompted. <a class="header-anchor" href="#insert-the-hardware-token-when-prompted" aria-label="Permalink to &quot;Insert the hardware token when prompted.&quot;">​</a></h2><p><strong>Note: Backups</strong> Configure a duplicate hardware token and store it securely as a backup.</p><h4 id="recommended-hardware-for-ufa" tabindex="-1">Recommended Hardware for UFA <a class="header-anchor" href="#recommended-hardware-for-ufa" aria-label="Permalink to &quot;Recommended Hardware for UFA&quot;">​</a></h4><ul><li><a href="https://www.yubico.com/product/security-key-c-nfc-by-yubico/" target="_blank" rel="noreferrer">Security Key C NFC by Yubico</a>: A budget-friendly Yubikey option offering phishing-resistant UFA.</li></ul><p><strong>Note: About Buying Yubikeys</strong> Higher-end Yubikeys offer additional features such as encryption and signature capability, which may not be necessary for all users.</p><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><ul><li><p><a href="https://www.cisa.gov/mfa" target="_blank" rel="noreferrer">CISA: What is MFA</a></p></li><li><p><a href="https://www.yubico.com/authentication-standards/fido-u2f/" target="_blank" rel="noreferrer">Yubico: FIDO U2F Authentication</a></p></li></ul><p>[Practices]</p>',39)])])}const f=a(i,[["render",n]]);export{p as __pageData,f as default};
